queries.query:
UPDATE cupom
SET uso_atual = uso_atual + 1
WHERE id = @Id;

INSERT INTO cupom (codigo, tipo_desconto, valor, data_expiracao, limite_uso)
VALUES (@Codigo, @TipoDesconto, @Valor, @DataExpiracao, @LimiteUso)
RETURNING id;

UPDATE pedido
SET status_pedido = @Status
WHERE id = @Id;

INSERT INTO pedido (
id, usuario_id, data_pedido, status_pedido,
total_pedido, mercadopago_pagamento_id,
preference_id, metodo_pagamento, cupom_id
)
VALUES (
@Id, @UserId, @OrderDate, @Status,
@TotalAmount, @MercadoPagoPaymentId,
@PaymentMethod, NULL, @CupomId
)
RETURNING id;

INSERT INTO item_pedido (
pedido_id, produto_id, produto_variacao_id,
quantidade, preco_unitario
)
VALUES (
@OrderId, @ProductId, @ProductVariationId,
@Quantity, @UnitPrice
);

INSERT INTO item_pedido (
pedido_id, produto_id, produto_variacao_id,
quantidade, preco_unitario
)
VALUES (
@OrderId, @ProductId, @ProductVariationId,
@Quantity, @UnitPrice
);

UPDATE pedido
SET preference_id = @PreferenceId
WHERE id = @Id;
